  "events": [
    {
      "trigger": "announced",
      "type": "Statement",
      "arguments": {
        "Speaker": [
          "The band"
        ],
        "Message": [
          "their break-up"
        ]
      }
    },
    {
      "trigger": "announced",
      "type": "Statement",
      "arguments": {
        "Speaker": [
          "The band"
        ],
        "Message": [
          "plans of doing one last farewell tour before officially disbanding"
        ]
      }
    },
    {
      "trigger": "announced",
      "type": "Statement",
      "arguments": {
        "Speaker": [
          "the band"
        ],
        "Message": [
          "the tour dates to take place in December 2012"
        ]
      }
    },
    {
      "trigger": "commented",
      "type": "Statement",
      "arguments": {
        "Speaker": [
          "The band"
        ],
        "Message": [
          "the tour was short due to December being the only available time window for all five members when they were free from any other commitments , especially Dallas Green who was touring with City and Colour and Wade MacNeil who was touring with Gallows"
        ]
      }
    },
    {
      "trigger": "announced",
      "type": "Statement",
      "arguments": {
        "Speaker": [
          "the band"
        ],
        "Message": [
          "they added another London date at the same venue , a day before , on December 2 , 2012"
        ]
      }
    }
  ]
